const pair = (title: string, text: string) => ({ title, text });
const solution = (title: string, text: string, audience: string, workflow: string, objective: string, service: string) => ({ title, text, audience, workflow, objective, service });
const ai = (title: string, text: string, review: string) => ({ title, text, review });
const outcome = (title: string, text: string, measure: string) => ({ title, text, measure });
const faq = (q: string, a: string) => ({ q, a });
type Input = Omit<IndustryDossier, "metaTitle" | "image" | "imageAlt" | "featured" | "schemaEnabled" | "ctaHeading" | "ctaText">;
function dossier(d: Input): IndustryDossier {
  return {
    ...d,
    metaTitle: `${d.title} Software Development`,
    image: `/images/sectors/${d.slug}-hero.webp`,
    imageAlt: `Editorial photograph representing ${d.title.toLowerCase()}`,
    featured: ["healthcare", "fintech", "manufacturing"].includes(d.slug),
    schemaEnabled: true,
    ctaHeading: `What needs to work better in ${d.title.toLowerCase()}?`,
    ctaText: "Bring the workflow, the systems it touches and the people who rely on it. We can discuss the constraints and a useful first scope - before choosing the technology.",
  };
}

